```
public class DownloadDbHelper extends SQLiteOpenHelper {

    private static final int DB_VERSION = 3;

    private static final String DB_NAME_DOWNLOAD = "lightshow_download.db";

    private static final String DB_TABLE_DOWNLOAD = "downloads";

    @Override

    public void onCreate(SQLiteDatabase db) { createTable(db); }

    @Override

    public void onUpgrade(SQLiteDatabase db, int oldVersion, int newVersion) {

        if (newVersion > oldVersion) createTable(db);  // 升级重建表

    }

    private void createTable(SQLiteDatabase db) {

        db.execSQL("CREATE TABLE " + DB_TABLE_DOWNLOAD + "("

            \+ "id INTEGER PRIMARY KEY AUTOINCREMENT,"

            \+ "url TEXT, status INTEGER, total INTEGER, downloaded INTEGER,"

            \+ "path TEXT, addTime INTEGER, md5 TEXT ...);");

    }

}
```

